(6093708, 896917, 87252, '<td valign="top">Cool idea, this must have taken you a while. I probably would have cropped out all of the background detail to really accentuate the detail.</td>', 'Cool idea, this must have taken you a while. I probably would have cropped out all of the background detail to really accentuate the detail.', '2010-07-15 06:45:58.000000', NULL, 1),
(6093709, 897277, 87252, '<td valign="top">Creative, a touch over saturated for my liking.</td>', 'Creative, a touch over saturated for my liking.', '2010-07-15 06:46:37.000000', NULL, 1),
(6093710, 896902, 87252, '<td valign="top">Nice abstract, painterly.</td>', 'Nice abstract, painterly.', '2010-07-15 06:47:36.000000', NULL, 1),
(6093712, 897569, 87252, '<td valign="top">Not the first thing that comes to mind when thinking ''rectangle'', but I like the interpretation and it is a nice subject.</td>', 'Not the first thing that comes to mind when thinking ''rectangle'', but I like the interpretation and it is a nice subject.', '2010-07-15 06:48:48.000000', NULL, 1),
(6093714, 897570, 87252, '<td valign="top">That is a slobbery dog! Not sure I like the composition, perhaps a closer crop on the dog''s head?</td>', 'That is a slobbery dog! Not sure I like the composition, perhaps a closer crop on the dog''s head?', '2010-07-15 06:50:28.000000', NULL, 1),
(6093715, 896377, 87252, '<td valign="top">Cool shot, I think a deeper DOF would have been nice to get all the detail in on the doors.</td>', 'Cool shot, I think a deeper DOF would have been nice to get all the detail in on the doors.', '2010-07-15 06:51:26.000000', NULL, 1),
(6093716, 897237, 87252, '<td valign="top">Wow I want to know what a multimedia super corridor is! This could be improved with fewer background details, I''m not sure how feasible that would have been but the bridge and lampposts are a bit distracting.</td>', 'Wow I want to know what a multimedia super corridor is! This could be improved with fewer background details, I''m not sure how feasible that would have been but the bridge and lampposts are a bit distracting.', '2010-07-15 06:53:40.000000', NULL, 1),
(6093717, 897625, 87252, '<td valign="top">Cool shot, maybe more of the background would have been interesting for context.</td>', 'Cool shot, maybe more of the background would have been interesting for context.', '2010-07-15 06:54:42.000000', NULL, 1),
(6093719, 896692, 87252, '<td valign="top">Cool idea, I think if you''d had a solid colour/ black background it might have been interesting.</td>', 'Cool idea, I think if you''d had a solid colour/ black background it might have been interesting.', '2010-07-15 06:56:30.000000', NULL, 1),
(6093720, 896489, 87252, '<td valign="top">Pro lighting, nice composition, great idea.</td>', 'Pro lighting, nice composition, great idea.', '2010-07-15 06:57:07.000000', NULL, 1),
(6093721, 897283, 87252, '<td valign="top">I really like the idea, my only criticisms would be that the lighting in the prints isn''t exactly the same as the final shot and the area in the top right is blown out.</td>', 'I really like the idea, my only criticisms would be that the lighting in the prints isn''t exactly the same as the final shot and the area in the top right is blown out.', '2010-07-15 06:59:39.000000', NULL, 1),
