(6093751, 897391, 87252, '<td valign="top">Wicked, now this I like, abstract but accessible, great colours and light.</td>', 'Wicked, now this I like, abstract but accessible, great colours and light.', '2010-07-15 07:28:30.000000', NULL, 1),
(6093753, 897514, 87252, '<td valign="top">Not a big fan of the over saturation but the square idea is creative.</td>', 'Not a big fan of the over saturation but the square idea is creative.', '2010-07-15 07:45:33.000000', NULL, 1),
(6093754, 897629, 87252, '<td valign="top">Very creative, nice shot.</td>', 'Very creative, nice shot.', '2010-07-15 07:46:15.000000', NULL, 1),
(6093755, 897616, 87252, '<td valign="top">Cool shot, I like the lighting.</td>', 'Cool shot, I like the lighting.', '2010-07-15 07:46:37.000000', NULL, 1),
