(6093760, 896551, 87252, '<td valign="top">Dominos is a good idea, I think that this shot would benefit from another light from camera right, a wider crop and sharper focus on the bottom right domino.</td>', 'Dominos is a good idea, I think that this shot would benefit from another light from camera right, a wider crop and sharper focus on the bottom right domino.', '2010-07-15 07:50:16.000000', NULL, 1),
(6093761, 897591, 87252, '<td valign="top">Lovely shot, taken at just the right time of day. Great textures.</td>', 'Lovely shot, taken at just the right time of day. Great textures.', '2010-07-15 07:50:55.000000', NULL, 1),
(6093763, 897654, 87252, '<td valign="top">The shadows seem a bit harsh here and there''s not much other than a rectangle-ish remote. Some kind of extra detail would have been great.</td>', 'The shadows seem a bit harsh here and there''s not much other than a rectangle-ish remote. Some kind of extra detail would have been great.', '2010-07-15 07:53:52.000000', NULL, 1),
(6093764, 897356, 87252, '<td valign="top">Great contrast in textures and colours, very interesting wall.</td>', 'Great contrast in textures and colours, very interesting wall.', '2010-07-15 07:54:31.000000', NULL, 1),
(6093768, 897283, 94437, '<td valign="top">Way too much planning went into this for me to attempt something like this, so Im really glad you did and you did it really well.<br/>Great imamge</td>', 'Way too much planning went into this for me to attempt something like this, so Im really glad you did and you did it really well.Great imamge', '2010-07-15 07:56:58.000000', NULL, 1),
