(6093775, 897217, 87252, '<td valign="top">Veeery nice, nice vision on this. I wish the girl was ever so slightly right in the frame to balance the composition a bit. Minor nitpick though.</td>', 'Veeery nice, nice vision on this. I wish the girl was ever so slightly right in the frame to balance the composition a bit. Minor nitpick though.', '2010-07-15 08:00:55.000000', NULL, 1),
(6093779, 897634, 87252, '<td valign="top">Lighthouse? Nicely seen rectangles.</td>', 'Lighthouse? Nicely seen rectangles.', '2010-07-15 08:01:27.000000', NULL, 1),
(6093780, 897420, 87252, '<td valign="top">Cool framing and great sky.</td>', 'Cool framing and great sky.', '2010-07-15 08:01:50.000000', NULL, 1),
