(6093787, 896781, 87252, '<td valign="top">Great shadows and colours, these buildings are fantastic.</td>', 'Great shadows and colours, these buildings are fantastic.', '2010-07-15 08:08:00.000000', NULL, 1),
(6093788, 897645, 87252, '<td valign="top">Nice bricks, it''s a shame the camera isn''t directly perpendicular to the central brick.</td>', 'Nice bricks, it''s a shame the camera isn''t directly perpendicular to the central brick.', '2010-07-15 08:09:11.000000', NULL, 1),
(6093789, 897258, 87252, '<td valign="top">Very minimalist.</td>', 'Very minimalist.', '2010-07-15 08:09:33.000000', NULL, 1),
(6093790, 896954, 87252, '<td valign="top">Great shadows and composition.</td>', 'Great shadows and composition.', '2010-07-15 08:10:14.000000', NULL, 1),
