(6095536, 897585, 43774, '<td valign="top">Yum!</td>', 'Yum!', '2010-07-17 09:51:25.000000', NULL, 1),
(6095609, 897391, 117912, '<td valign="top">Beautiful detail and composition.</td>', 'Beautiful detail and composition.', '2010-07-17 11:25:56.000000', NULL, 1),
(6095610, 896976, 117912, '<td valign="top">Love the angle and the reflections.</td>', 'Love the angle and the reflections.', '2010-07-17 11:26:41.000000', NULL, 1),
(6095616, 897281, 10785, '<td valign="top">The photo meets the challenge by depicting rectangles. I think it suffers from being underexposed. It could be composed better to add some interest. It looks like you took a shot of your hard work of the day to show your pride of accomplishment!</td>', 'The photo meets the challenge by depicting rectangles. I think it suffers from being underexposed. It could be composed better to add some interest. It looks like you took a shot of your hard work of the day to show your pride of accomplishment!', '2010-07-17 11:52:22.000000', NULL, 1),
(6095633, 897641, 10785, '<td valign="top">It appears there are some focusing and sharpness issues here, but then again it could be on purpose for arts sake... (sorry art!! lol)<br/> <br/>I don''t think the lens flare adds anything to the picture and the white balance is definitely something I am not used to seeing... This photo just confuses me apparently!</td>', 'It appears there are some focusing and sharpness issues here, but then again it could be on purpose for arts sake... (sorry art!! lol) I don''t think the lens flare adds anything to the picture and the white balance is definitely something I am not used to seeing... This photo just confuses me apparently!', '2010-07-17 12:36:58.000000', NULL, 1),
(6095635, 897120, 10785, '<td valign="top">Good texture. Meets the challenge. Due to the overwhelming greyness of it all it sort of lacks interest for me.</td>', 'Good texture. Meets the challenge. Due to the overwhelming greyness of it all it sort of lacks interest for me.', '2010-07-17 12:38:25.000000', NULL, 1),
(6095636, 897570, 10785, '<td valign="top">Good vision... but with the other dog''s butt in the photo and the placement of the majority of the subjects face in the lower middle of the frame, it just sort of feels like you took the shot without considering any compositional aspects of the photo.</td>', 'Good vision... but with the other dog''s butt in the photo and the placement of the majority of the subjects face in the lower middle of the frame, it just sort of feels like you took the shot without considering any compositional aspects of the photo.', '2010-07-17 12:40:52.000000', NULL, 1),
(6095638, 897297, 10785, '<td valign="top">Variations of this theme have been done to death in different challenge topics since 2002... So it''s humorous but over-used.</td>', 'Variations of this theme have been done to death in different challenge topics since 2002... So it''s humorous but over-used.', '2010-07-17 12:43:31.000000', NULL, 1),
(6095639, 897610, 61396, '<td valign="top">I like how the chain is contrasted against various backgrounds. Don''t know about rectangles, so not voting.</td>', 'I like how the chain is contrasted against various backgrounds. Don''t know about rectangles, so not voting.', '2010-07-17 12:43:41.000000', NULL, 1),
(6095641, 897577, 10785, '<td valign="top">Nice shadow play... but the subject is somewhat uninteresting and over-ordinary.</td>', 'Nice shadow play... but the subject is somewhat uninteresting and over-ordinary.', '2010-07-17 12:44:35.000000', NULL, 1),
(6095643, 897296, 10785, '<td valign="top">A good find of the shape. It is somewhat lacking in color. A nicer sunset skyline or a cloudy sky could have added some more interest.</td>', 'A good find of the shape. It is somewhat lacking in color. A nicer sunset skyline or a cloudy sky could have added some more interest.', '2010-07-17 12:46:44.000000', NULL, 1),
